window.__finlexDocLoaded(10035,{"id":10035,"articles":[{"id":1000086,"no":"Overview","heading":"Scope & Key Requirements (Public Summary)","text":"Deals with the auditor's responsibilities in the audit of financial statements relating to going concern and the implications for the auditor's report (Revised 2024, published April 2025).","seq":0},{"id":1000087,"no":"ISA 570 (Rev. 2024)","heading":"Going Concern Assessment, 12-Month Window & Reporting","text":"• Management's assessment (ISA 570 Revised 2024, published April 2025): strengthens auditor evaluation of management's going concern assessment over at least 12 months from the date of approval of the financial statements.\n• Reporting outcomes: adequate disclosure of Material Uncertainty → unmodified opinion with dedicated 'Material Uncertainty Related to Going Concern' section; inadequate disclosure → Qualified or Adverse opinion; inappropriate going concern basis → Adverse opinion (converged with China CSA 1324).","seq":1},{"id":1000088,"no":"Official Access","heading":"Official Handbook & Reference Entry","text":"Official source (IAASB 2026 Handbook): https://www.iaasb.org/publications/2026-handbook-international-quality-management-auditing-review-sustainability-and-other-assurance\nStatus: in_force. Detailed paragraph-level summaries and practice notes can be expanded incrementally.\n2026 Handbook Volume: Volume 1 (ISQM 1–2, ISA 200–720)\nLocal Private Full-Text Import: Place the free official 2026 IAASB Handbook PDF in local_pdfs/ and run `python3 scripts/import_private_intl_pdfs.py`.","seq":2}]});
